    {
        unimplemented!()
    }

    pub proof fn validate(tracked &self)
        ensures
            self.wf(),
    {
        use_type_invariant(self);
    }

    pub proof fn validate_full(tracked &self)
        requires
            self.is_full(),
        ensures
            self.not_empty(),
            self.frac() == TOTAL,
            self.wf(),
    {
        use_type_invariant(self);
    }

    #[verifier::external_body]
    pub proof fn validate_with_frac(tracked &self, tracked frac: &Count<T, TOTAL>)
