/// Attempts to acquire an upread lock.
///
/// This function will never spin-wait and will return immediately.
pub fn try_upread(&self) -> Option<RwLockUpgradeableGuard<'_, T, G>> {
    proof_decl!{
        let tracked mut upgrade_guard_token: Option<OneLeftOwner<HalfPerm<T>, NoPerm<T>, 3>> = None;
        let tracked mut retract_upgrade_token: Option<UniqueToken> = None;
    }
    proof!{
        use_type_invariant(self);
        lemma_consts_properties();
    }
    let guard = G::guard();
    // let lock = self.lock.fetch_or(UPGRADEABLE_READER, Acquire) & (WRITER | UPGRADEABLE_READER);
    let lock_val = atomic_with_ghost!(
        self.lock => fetch_or(UPGRADEABLE_READER);
        update prev -> next;
        returning ret;
        ghost g => {
            let prev_val: usize = prev as usize;
            if prev_val & (WRITER | UPGRADEABLE_READER) == 0 {
                // Successfully acquired upread lock
                // Transfer tokens from ghost state to local variables
                proof {
                    // Use tracked assignment to extract tokens from g
                    upgrade_guard_token = g.upreader_guard_token;
                    retract_upgrade_token = g.upread_retract_token;
                    // Now g's tokens are moved, so we need to set them to None
                    g.upreader_guard_token = None;
                    g.upread_retract_token = None;
                }
            }
        }
    );
    let lock = lock_val & (WRITER | UPGRADEABLE_READER);
    if lock == 0 {
        return Some(
            RwLockUpgradeableGuard {
                inner: self,
                guard,
                tracked_token: Tracked(upgrade_guard_token.tracked_unwrap()),
            },
        );
    } else if lock == WRITER {
        // self.lock.fetch_and(!(UPGRADEABLE_READER as usize));
        atomic_with_ghost!(
            self.lock => fetch_and(!(UPGRADEABLE_READER as usize));
            update prev -> next;
            ghost g => {
                let prev_val: usize = prev as usize;
                if prev_val & (WRITER | UPGRADEABLE_READER) == WRITER {
                    // Revert the upread acquisition since there's a writer
                    proof {
                        g.upread_retract_token = retract_upgrade_token;
                    }
                }
            }
        );
    }
    None
}

